const e=$json;
const wf=(e.workflow&&e.workflow.name)||'(unknown workflow)';
const node=(e.execution&&e.execution.lastNodeExecuted)||'(unknown node)';
const msg=(e.execution&&e.execution.error&&(e.execution.error.message||e.execution.error.description))||'(no message)';
const url=(e.execution&&e.execution.url)||'';
const when=new Date().toLocaleString('en-US',{timeZone:'America/New_York'});
const esc=s=>String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const html='<div style="font:14px Segoe UI,Arial;color:#222;max-width:760px">'
+'<h2 style="color:#B00020;margin:0 0 6px">RT 21 automation failed</h2>'
+'<div style="color:#667;font-size:13px;margin-bottom:16px">'+esc(when)+' (Eastern)</div>'
+'<table cellpadding="7" cellspacing="0" style="border-collapse:collapse;font:13px Segoe UI,Arial">'
+'<tr><td style="color:#556">Workflow</td><td><b>'+esc(wf)+'</b></td></tr>'
+'<tr><td style="color:#556">Failed at node</td><td><b>'+esc(node)+'</b></td></tr>'
+'<tr><td style="color:#556;vertical-align:top">Error</td><td>'+esc(String(msg).slice(0,600))+'</td></tr>'
+'</table>'
+(url?'<p style="margin:16px 0 0"><a href="'+esc(url)+'">Open the failed execution in n8n</a></p>':'')
+'<p style="margin:18px 0 0;color:#556">The daily email will refuse to send if the workbook has not refreshed today, '
+'so a failed export will not put stale figures in front of the group.</p></div>';
return [{json:{payload:{message:{subject:'RT 21 automation failed — '+wf,
  body:{contentType:'HTML',content:html},
  toRecipients:[{emailAddress:{address:'gpress@engelmansbakery.com'}}]},saveToSentItems:true}}}];
